from collections import deque
from heapq import heappush, heappop

def shortest_path(graph, source, target):
    if source not in graph or target not in graph:
        return float("inf"), None

    # Helper function to check if the target is reachable from source
    def is_reachable(source, target):
        distances = {node: float("inf") for node in graph}
        distances[source] = 0
        queue = deque([source])
        while queue:
            current = queue.popleft()
            for neighbor, weight in graph.get(current, []):
                if distances[current] + weight < distances[neighbor]:
                    distances[neighbor] = distances[current] + weight
                    if neighbor == target:
                        return True
                    queue.append(neighbor)
        return False

    # Check if target is reachable from source
    if not is_reachable(source, target):
        return float("inf"), None

    # Function to find the shortest path using Bellman-Ford algorithm
    def bellman_ford(graph, source, target):
        distances = {node: float("inf") for node in graph}
        distances[source] = 0
        for _ in range(len(graph)):
            for node in graph:
                for neighbor, weight in graph[node]:
                    if distances[node] + weight < distances[neighbor]:
                        distances[neighbor] = distances[node] + weight
        return distances[target]

    # Find the shortest path
    shortest_distance = bellman_ford(graph, source, target)

    # Collect the path
    path = []
    if shortest_distance == float("inf"):
        return float("inf"), None

    current = target
    while current != source:
        for neighbor, weight in graph[current]:
            if distances[neighbor] + weight == distances[current]:
                path.append(current)
                current = neighbor
                break
    path.append(source)
    path.reverse()

    return shortest_distance, path

