def shortest_path(graph, source, target):
    import heapq

    # Initialize the priority queue with (0, source) and an empty set of explored nodes
    priority_queue = [(0, source)]
    explored = set()
    path_dict = {source: None}

    # Continue until the priority queue is empty
    while priority_queue:
        # Extract the node with the smallest distance
        current_distance, current_node = heapq.heappop(priority_queue)
        if current_node in explored:
            continue
        explored.add(current_node)

        # Check if we have reached the target node
        if current_node == target:
            reconstruct_path = []
            while current_node is not None:
                reconstruct_path.append(current_node)
                current_node = path_dict.get(current_node, None)
            reconstruct_path.reverse()
            return (current_distance, reconstruct_path)

        # Explore neighbors
        for neighbor, weight in graph.get(current_node, []):
            if neighbor in explored:
                continue
            new_distance = current_distance + weight
            if neighbor not in path_dict or new_distance < path_dict[neighbor][0]:
                path_dict[neighbor] = (new_distance, current_node)
                heapq.heappush(priority_queue, (new_distance, neighbor))

    # If the target is unreachable
    return (float("inf"), None)

