def shortest_path(graph, source, target):
    # Initialize the distance dictionary and the previous node dictionary
    distance = {node: float("inf") for node in graph}
    distance[source] = 0
    previous = {node: None for node in graph}

    # Define a function to check if the shortest path to a node has been found.
    def shortest_path_to_target(node):
        if node == target:
            return True
        return any(
            shortest_path_to_target(neighbor)
            for neighbor, _ in graph[node]
            if distance[node] + neighbor[1] < distance[neighbor[0]]
        )

    # Define a function to update the graph state by relaxing edges.
    def relax(source, target):
        for neighbor, weight in graph[target]:
            new_distance = distance[target] + weight
            if new_distance < distance[neighbor]:
                distance[neighbor] = new_distance
                previous[neighbor] = target

    # Find the shortest path to the target from all nodes reachable from the source
    for _ in range(len(graph)):
        for node in graph:
            if distance[node] < float("inf"):
                for neighbor, weight in graph[node]:
                    relax(node, neighbor)

    # If there is no path from source to target, return infinity and None
    if distance[target] == float("inf"):
        return (float("inf"), None)

    # Reconstruct the path from previous
    path = []
    current = target
    while current is not None:
        path.append(current)
        current = previous[current]
    path.reverse()

    return (distance[target], path)
