def shortest_path(graph, source, target):
    if source not in graph or target not in graph:
        return float("inf"), None

    # Initialize distances and previous nodes
    distances = {node: float("inf") for node in graph}
    distances[source] = 0
    previous = {node: None for node in graph}

    # Initialize the queue with the source node
    queue = [(0, source)]

    # Relax edges |V| - 1 times
    for _ in range(len(graph) - 1):
        while queue:
            distance, current_node = queue.pop(0)
            if distance > distances[current_node]:
                continue
            for neighbor, weight in graph[current_node]:
                distance_to_neighbor = distance + weight
                if distance_to_neighbor < distances[neighbor]:
                    distances[neighbor] = distance_to_neighbor
                    previous[neighbor] = current_node
                    queue.append((distance_to_neighbor, neighbor))

    # Check for negative-weight cycles
    for current_node, previous_node in previous.items():
        for neighbor, weight in graph[current_node]:
            if distances[current_node] + weight < distances[neighbor]:
                return float("inf"), None

    # Construct the path
    path = []
    node = target
    while node is not None:
        path.append(node)
        node = previous[node]
    path.reverse()

    return distances[target], path

