    distance = {node: float('inf') for node in graph}
    distance[source] = 0
    path = {node: None for node in graph}

    while True:
        # Find the node with the smallest distance that hasn't been finalized yet
        finalized = True
        for node in graph:
            if distance[node] < float('inf') and node not in path.values():
                finalized = False
                break

        if finalized:
            # If no node is finalized, the target is unreachable
            return float('inf'), None

        # Choose the node to process next
        node_to_process = None
        for node in graph:
            if distance[node] < float('inf'):
                if node_to_process is None or distance[node] + graph[node][0][1] < distance[node_to_process] + graph[node_to_process][0][1]:
                    node_to_process = node

        # Update distances and paths for the chosen node
        for neighbor, weight in graph[node_to_process]:
            if distance[node_to_process] + weight < distance[neighbor]:
                distance[neighbor] = distance[node_to_process] + weight
                path[neighbor] = node_to_process

        # Remove the finalized node from consideration in the next iteration
        del graph[node_to_process]

    return distance[target], [target] if target in path else None

