            if distance < distances[neighbor]:
                distances[neighbor] = distance
                parents[neighbor] = current_node
                # Add to queue with current distance
                queue.append((distance, neighbor))

        # If we've visited all nodes, we can exit early
        if all(distances[node] != float('inf') for node in graph):
            break

