    if source == target:
        return (0, [source])

    # Initialize distances and paths
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    paths = {node: [] for node in graph}
    paths[source] = [source]

    # Set of nodes to be inspected
    inspected = set()

    while target not in inspected:
        min_distance = float('inf')
        min_node = None

        # Find the node with the smallest distance that hasn't been inspected yet
        for node in graph:
            if node not in inspected and distances[node] < min_distance:
                min_distance = distances[node]
                min_node = node

        # No closer node found, stop the loop
        if min_node is None:
            return (float('inf'), None)

        inspected.add(min_node)

        # Explore neighbors
        for neighbor, weight in graph[min_node]:
            if distances[min_node] + weight < distances[neighbor]:
                distances[neighbor] = distances[min_node] + weight
                paths[neighbor] = paths[min_node] + [neighbor]

    return (distances[target], paths[target])

