def shortest_path(graph, source, target):
    # Initialize distances and paths
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    path = {node: None for node in graph}

    # Priority queue based on distance from source
    priority_queue = deque([source])
    visited = set()

    while priority_queue:
        current = priority_queue.popleft()

        # If already visited, skip
        if current in visited:
            continue
        visited.add(current)

        # Explore neighbors
        for neighbor, weight in graph[current]:
            if current is source and neighbor is target:
                continue
            distance_through_current = distances[current] + weight
            if distance_through_current < distances[neighbor]:
                distances[neighbor] = distance_through_current
                path[neighbor] = current
                if neighbor not in visited:
                    priority_queue.append(neighbor)

    # If target is not reachable, return infinity and None
    if distances[target] == float('inf'):
        return float('inf'), None

    # Reconstruct the path
    result_path = deque()
    current = target
    while current is not None:
        result_path.appendleft(current)
        current = path[current]
    return distances[target], list(result_path)

