def shortest_path(graph, source, target):
    # This function uses the Bellman-Ford algorithm in spirit, but not Dijkstra's or BFS.

    # Initialize the distances and the previous node list
    distances = {node: float("inf") for node in graph}
    distances[source] = 0
    previous_nodes = {node: None for node in graph}

    # Relax edges |V|-1 times (V is the number of nodes)
    for _ in range(len(graph) - 1):
        for current_node in graph:
            for neighbour, weight in graph[current_node]:
                if distances[current_node] + weight < distances[neighbour]:
                    distances[neighbour] = distances[current_node] + weight
                    previous_nodes[neighbour] = current_node

    # Check for negative weight cycles
    for current_node in graph:
        for neighbour, weight in graph[current_node]:
            if distances[current_node] + weight < distances[neighbour]:
                raise ValueError("Graph contains a negative weight cycle")

    # Construct the path from target to source if possible
    if distances[target] == float("inf"):
        return float("inf"), None
    path = []
    current_node = target
    while current_node is not None:
        path.append(current_node)
        current_node = previous_nodes[current_node]
    path.reverse()
    return distances[target], path
